@Component("fXTrade-handler")
@ProcessingGroup("fXTrade-processing-group")
public class FXTradeEventHandler {
	
	// core constructor
	FXTradeEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateFXTradeEvent
     */
    @EventHandler
    public void handle( CreateFXTradeEvent event) {
        entityManager.persist(new FXTrade(event.getFXTradeId(), event.getTradeReference(), event.getTradeDate(), event.getSettlementDate(), event.getAmountSold(), event.getAmountBought(), event.getRate(), event.getCustomer(), event.getBank(), event.getExchangeRate(), event.getSourceAccount(), event.getDestinationAccount(), event.getTransaction(), event.getStatus()));
    }

    /*
     * @param	event UpdateFXTradeEvent
     */
    @EventHandler
    public FXTrade handle( UpdateFXTradeEvent event) {
    	entityManager.merge(new FXTrade(event.getFXTradeId(), event.getTradeReference(), event.getTradeDate(), event.getSettlementDate(), event.getAmountSold(), event.getAmountBought(), event.getRate(), event.getCustomer(), event.getBank(), event.getExchangeRate(), event.getSourceAccount(), event.getDestinationAccount(), event.getTransaction(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteFXTradeEvent
     */
    @EventHandler
    public void on( DeleteFXTradeEvent event) {
    	FXTrade entity = new FXTrade();
   
    	// ------------------------------------------
    	// apply the FXTradeId
    	// ------------------------------------------
    	entity.setFXTradeId( event.getFXTradeId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final FXTradeRepository fXTradeEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(FXTradeEventHandler.class.getName());

}
